//! Voice resume tokens, ported from `server/src/ws/voice-resume-token.ts`.
//!
//! This module is a **wire-compatible** port, not a reimplementation with a
//! nicer format. During a migration the Node server and this crate run
//! side by side behind the same load balancer, and a token minted by one
//! must verify on the other: a rolling deploy that cannot do that turns a
//! deploy into a hangup, which is the one thing
//! [`docs/VOICE_RESUME.md`] is built to prevent. `tests/resume_parity.rs`
//! pins that against vectors generated by the TypeScript original.
//!
//! The rules that actually matter, copied from the original:
//!
//! * `peerId` is on every roster, so "claim this unused id" after a restart
//!   would let anyone who read the roster take someone else's slot. The HMAC
//!   is the proof of ownership.
//! * A bad or missing token is a **cold join**, never an error. Every failure
//!   here returns `None`.
//! * The signing key is derived from `CLERK_SECRET_KEY` through a
//!   purpose-bound HMAC so a resume MAC cannot be replayed against anything
//!   else that later signs with the same secret.

use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use base64::Engine as _;
use hmac::{Hmac, Mac};
use serde::{Deserialize, Serialize};

pub use crate::VoiceRoomTransport;
use sha2::Sha256;

/// How long a disconnected peer is held for a reconnect on the same process.
pub const VOICE_RESUME_TTL_MS: i64 = 90_000;
/// How long the HMAC itself stays valid, which has to outlive a real call
/// rather than the 90s blip window: after a restart the token is the only
/// thing left to reconstruct the seat from.
pub const VOICE_RESUME_TOKEN_TTL_MS: i64 = 8 * 60 * 60 * 1000;

/// Namespace for the derived key. Changing this invalidates every outstanding
/// token, which is a hangup: bump only on a deliberate break.
const RESUME_KEY_CONTEXT: &[u8] = b"pqp-voice-resume";

/// Stand-in key when the dev auth bypass is on, matching the server.
pub const DEV_RESUME_SECRET: &str = "pqp-dev-voice-resume";

/// Source of the signing key, mirroring `resumeSecret()`.
///
/// Resolved per call rather than cached, because the server reads
/// `process.env` per call too and tests flip it between cases.
#[derive(Debug, Clone, Default)]
pub struct ResumeSecret {
    clerk_secret_key: Option<String>,
    dev_auth_bypass: bool,
}

impl ResumeSecret {
    pub fn new(clerk_secret_key: Option<String>, dev_auth_bypass: bool) -> Self {
        Self {
            clerk_secret_key,
            dev_auth_bypass,
        }
    }

    /// `CLERK_SECRET_KEY`, else the dev bypass stand-in, else nothing.
    pub fn from_env() -> Self {
        Self::new(
            std::env::var("CLERK_SECRET_KEY")
                .ok()
                .filter(|v| !v.is_empty()),
            std::env::var("DEV_AUTH_BYPASS").as_deref() == Ok("true"),
        )
    }

    /// The derived key, or `None` when the deployment has nothing to sign
    /// with. `None` means resume is off, not broken: callers cold-join.
    fn derive(&self) -> Option<String> {
        let raw = self
            .clerk_secret_key
            .as_deref()
            .filter(|v| !v.is_empty())
            .or(self.dev_auth_bypass.then_some(DEV_RESUME_SECRET))?;
        Some(base64url(&hmac_sha256(raw.as_bytes(), RESUME_KEY_CONTEXT)))
    }
}

/// Claims carried inside the token. Field order is the serialized order: the
/// payload is hashed as bytes, so a reordered struct changes every token.
#[derive(Debug, Serialize, Deserialize)]
struct Claims {
    /// Format version. Anything other than 1 is refused.
    v: i64,
    u: String,
    p: String,
    c: String,
    t: String,
    /// Expiry, ms since epoch.
    e: i64,
    /// SFU region, only present in multi-region deployments. Written as an
    /// absent field so a single-region token stays byte for byte what it was.
    ///
    /// Typed loosely on purpose. The server only checks `typeof r ===
    /// "string"`, so a token whose `r` is a number still verifies and reads as
    /// the home region. A strict `Option<String>` here would reject tokens the
    /// server accepts, which is a hangup on a rolling deploy.
    #[serde(skip_serializing_if = "Option::is_none")]
    r: Option<serde_json::Value>,
}

/// What a verified token vouches for.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VerifiedResume {
    pub user_id: String,
    pub peer_id: String,
    pub voice_channel_id: String,
    pub transport: VoiceRoomTransport,
    /// The region the token remembers, or `None` when it names none.
    pub region: Option<String>,
}

/// The room a resume is being claimed for.
#[derive(Debug, Clone, Copy)]
pub struct ResumeClaims<'a> {
    pub user_id: &'a str,
    pub peer_id: &'a str,
    pub voice_channel_id: &'a str,
}

/// Mint a resume token, or `None` when the deployment has no signing key.
pub fn mint_voice_resume_token(
    secret: &ResumeSecret,
    user_id: &str,
    peer_id: &str,
    voice_channel_id: &str,
    transport: VoiceRoomTransport,
    region: Option<&str>,
    now: i64,
) -> Option<String> {
    let key = secret.derive()?;
    let claims = Claims {
        v: 1,
        u: user_id.to_string(),
        p: peer_id.to_string(),
        c: voice_channel_id.to_string(),
        t: match transport {
            VoiceRoomTransport::Mesh => "mesh",
            VoiceRoomTransport::Livekit => "livekit",
        }
        .to_string(),
        e: now.checked_add(VOICE_RESUME_TOKEN_TTL_MS)?,
        r: region
            .filter(|r| !r.is_empty())
            .map(serde_json::Value::from),
    };
    let payload = base64url(&serde_json::to_vec(&claims).expect("claims are always serializable"));
    Some(format!(
        "{payload}.{}",
        base64url(&hmac_sha256(key.as_bytes(), payload.as_bytes()))
    ))
}

/// Verify a token against the room it was presented for.
///
/// Every failure mode returns `None`, which the caller turns into a cold join.
pub fn verify_voice_resume_token(
    secret: &ResumeSecret,
    token: Option<&str>,
    expected: ResumeClaims<'_>,
    now: i64,
) -> Option<VerifiedResume> {
    let token = token.filter(|t| !t.is_empty())?;
    let key = secret.derive()?;
    // lastIndexOf: the payload never contains a dot, but read it the same way
    // the server does so a hand-written token behaves identically on both.
    let dot = token.rfind('.')?;
    if dot == 0 {
        return None;
    }
    let (payload, mac) = token.split_at(dot);
    let mac = &mac[1..];

    let expected_mac = hmac_sha256(key.as_bytes(), payload.as_bytes());
    let presented_mac = URL_SAFE_NO_PAD.decode(mac).ok()?;
    if !constant_time_eq(&expected_mac, &presented_mac) {
        return None;
    }

    let claims: Claims = serde_json::from_slice(&URL_SAFE_NO_PAD.decode(payload).ok()?).ok()?;
    if claims.v != 1 || claims.e < now {
        return None;
    }
    let transport = match claims.t.as_str() {
        "mesh" => VoiceRoomTransport::Mesh,
        "livekit" => VoiceRoomTransport::Livekit,
        _ => return None,
    };
    if claims.u != expected.user_id
        || claims.p != expected.peer_id
        || claims.c != expected.voice_channel_id
    {
        return None;
    }
    let region = match &claims.r {
        Some(serde_json::Value::String(r)) if !r.is_empty() => Some(r.clone()),
        _ => None,
    };
    Some(VerifiedResume {
        user_id: claims.u,
        peer_id: claims.p,
        voice_channel_id: claims.c,
        transport,
        region,
    })
}

fn hmac_sha256(key: &[u8], message: &[u8]) -> Vec<u8> {
    let mut mac = Hmac::<Sha256>::new_from_slice(key).expect("HMAC accepts keys of any length");
    mac.update(message);
    mac.finalize().into_bytes().to_vec()
}

fn base64url(bytes: &[u8]) -> String {
    URL_SAFE_NO_PAD.encode(bytes)
}

/// Length-checked constant-time compare. `constant_time_eq` in the dependency
/// list would be cleaner; this avoids a crate for eight lines.
fn constant_time_eq(left: &[u8], right: &[u8]) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut diff = 0u8;
    for (a, b) in left.iter().zip(right.iter()) {
        diff |= a ^ b;
    }
    diff == 0
}
